{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Norethisterone absolute oral bioavailability was measured in 6 female volunteers after 1 mg oral vs intravenous dosing, with a mean of 64% and range 47–73%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Etonogestrel absolute oral bioavailability after oral desogestrel 150 µg vs intravenous 3-keto-desogestrel was 76.1 ± 22.5% in healthy female volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Absolute oral bioavailability of a 1500 mg tablet was 57% in healthy volunteers in the fasted state, directly matching the fasted condition.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred evidence molecules show absolute or oral bioavailability values well above the 20% threshold, with several direct absolute bioavailability measurements in humans. The fasted-state record also supports high bioavailability.",
  "evidence_gaps": [
    "Only one supplied record explicitly reports fasted-state conditions; other records use ordinary oral administration conditions.",
    "Some records report bioavailability type as unspecified rather than absolute, though their numeric values remain clearly above the threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

